// Project-time notes are independent of clip trims and source analysis.
export function sanitizeEditMarkers(markers){return(Array.isArray(markers)?markers:[]).slice(0,500).filter(m=>m&&typeof m.id==='string'&&Number.isFinite(m.time)&&m.time>=0&&m.time<=86400).map(m=>({id:m.id.slice(0,80),time:m.time,label:String(m.label||'編集の目印').slice(0,80)})).sort((a,b)=>a.time-b.time)}
export function addEditMarker(project,time,id){project.editMarkers=sanitizeEditMarkers(project.editMarkers);if(!Number.isFinite(time)||time<0||time>86400||project.editMarkers.length>=500)return null;if(project.editMarkers.some(m=>Math.abs(m.time-time)<.001))return null;const marker={id,time,label:'編集の目印 '+(project.editMarkers.length+1)};project.editMarkers.push(marker);project.editMarkers.sort((a,b)=>a.time-b.time);return marker}
export function nextEditMarker(markers,time,direction){const ordered=sanitizeEditMarkers(markers);return direction>0?ordered.find(m=>m.time>time+.001):ordered.filter(m=>m.time<time-.001).at(-1)}
